// Built-in Burumy sticker packs, character emoji and character reactions
// (our own art from the v1 pack; generated list, do not edit by hand).

class StickerPack {
  const StickerPack(this.id, this.items);
  final String id;
  final List<String> items;

  String asset(String item) => 'assets/stickers/$id/$item.webp';

  /// Moving stickers have 'a' + number in the middle: buru_a01_hello.
  static bool moving(String item) => item.split('_').elementAtOrNull(1)?.startsWith('a') ?? false;
}

