final _assetOf = <String, String>{
  for (final p in stickerPacks)
    for (final i in p.items) i: p.asset(i),
};

/// Asset path for a sticker id like 'buru_01_hello' (null if unknown).
String? stickerAsset(String id) => _assetOf[id];

final _emojiIds = {for (final g in charEmojiGroups.values) ...g};

/// Asset of a character emoji ('buru_e2_love'), or null.
String? charEmojiAsset(String id) => _emojiIds.contains(id) ? 'assets/stickers/emoji/$id.webp' : null;

final _reactIds = charReactions.toSet();

/// Asset of a character reaction ('buru_r2_love'), or null for a plain emoji.
String? charReactionAsset(String key) => _reactIds.contains(key) ? 'assets/stickers/react/$key.webp' : null;
